// Types, colours and helpers for the OMN Church Map (/map).
// Data files are generated by tools/church-map/build_data.py into public/church-map/.

export type Church = {
  id: number;
  name: string;
  area: AreaKey;
  cityArea: string;
  street: string;
  city: string;
  state: string;
  zip: string;
  lat: number;
  lon: number;
  geocode: "esri" | "census";
  county: string | null;
  inOhio: boolean;
  pastor: string | null;
  phone: string | null;
  status: string | null;
  attendance: number | null;
  adherents: number | null;
  members: number | null;
  conversions: number | null;
  waterBaptisms: number | null;
  spiritBaptisms: number | null;
};

export type AreaKey =
  | "NORTHWEST"
  | "WEST CENTRAL"
  | "NORTH CENTRAL"
  | "GREATER CLEVELAND"
  | "GREATER AKRON"
  | "EAST CENTRAL"
  | "NORTHEAST"
  | "YOUNGSTOWN-WARREN"
  | "GREATER DAYTON"
  | "GREATER CINCINNATI"
  | "GREATER COLUMBUS WEST"
  | "GREATER COLUMBUS EAST"
  | "SOUTH CENTRAL"
  | "SOUTHEAST";

export type CountyProps = {
  name: string;
  label: [number, number];
  geoid: string;
  areas: AreaKey[];
  population: number | null;
  agChurches: number | null;
  peoplePerAgChurch: number | null;
  unclaimedPct: number | null;
  attendPct: number | null;
  congregations: number | null;
  adherentsPct: number | null;
};

export type AreaProps = {
  key: AreaKey;
  name: string;
  region: number;
  presbyter: string;
  counties: string[];
  label: [number, number];
};

type Feature<P> = { type: "Feature"; properties: P; geometry: GeoJSON.Geometry };

export type GeoData = {
  regions: { id: number; executivePresbyter: string }[];
  state: Feature<Record<string, never>>;
  mask: Feature<Record<string, never>>;
  areas: { type: "FeatureCollection"; features: Feature<AreaProps>[] };
  regionShapes: { type: "FeatureCollection"; features: Feature<{ region: number }>[] };
  counties: { type: "FeatureCollection"; features: Feature<CountyProps>[] };
  columbusSplit: [number, number][];
};

