export const nf = new Intl.NumberFormat("en-US");

export function fmt(n: number | null | undefined) {
  return n == null ? "—" : nf.format(n);
}

export function titleCase(s: string) {
  return s
    .toLowerCase()
    .replace(/(^|[\s\-/])([a-z])/g, (_, a, b) => a + b.toUpperCase())
    .replace(/\bOf\b/g, "of")
    .replace(/\bAnd\b/g, "and");
}

export function formatPhone(p: string | null) {
  if (!p) return null;
  const d = p.replace(/\D/g, "");
  if (d.length !== 10) return p;
  return `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
}

/** "Rev Todd E Troyer" -> "Rev. Todd E. Troyer" */
export function formatPastor(p: string | null) {
  if (!p) return null;
  return p
    .replace(/^(Rev|Mr|Mrs|Ms|Dr|Chp)\s/, "$1. ")
    .replace(/\b([A-Z])\b(?!\.)/g, "$1.");
}

export function milesBetween(a: { lat: number; lon: number }, b: { lat: number; lon: number }) {
  const R = 3958.8;
  const toR = (d: number) => (d * Math.PI) / 180;
  const dLat = toR(b.lat - a.lat);
  const dLon = toR(b.lon - a.lon);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(toR(a.lat)) * Math.cos(toR(b.lat)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

export function directionsUrl(c: Church) {
  const q = encodeURIComponent(`${c.name}, ${c.street}, ${c.city}, ${c.state} ${c.zip}`);
  return `https://www.google.com/maps/search/?api=1&query=${q}`;
}

export function searchText(c: Church) {
  return `${c.name} ${c.city} ${c.cityArea} ${c.pastor ?? ""} ${c.county ?? ""} ${c.zip}`.toLowerCase();
}
